// Column conventions shared by every table (ADR-0004).

import { sql } from 'drizzle-orm';
import { type AnyPgColumn, check, timestamp, uuid } from 'drizzle-orm/pg-core';

/** UUIDv7 primary key generated by PostgreSQL 18, so ids sort by creation time. */
export const primaryId = () => uuid('id').primaryKey().default(sql`uuidv7()`);

/** Timestamps are always `timestamptz` (stored in UTC). */
export const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

/** Kept current by the `set_updated_at` trigger (migration 0005), so no caller can forget it. */
export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();

/** Catalog rows are archived, never deleted (ADR-0004): a null value means the row is live. */
export const archivedAt = () => timestamp('archived_at', { withTimezone: true });

/** A required text column that is not empty or whitespace, with an upper bound. */
export const boundedText = (name: string, column: AnyPgColumn, max: number) =>
  check(name, sql`length(btrim(${column})) between 1 and ${sql.raw(String(max))}`);

/** An optional text column: either null, or not blank and within the bound. */
export const optionalBoundedText = (name: string, column: AnyPgColumn, max: number) =>
  check(
    name,
    sql`${column} is null or length(btrim(${column})) between 1 and ${sql.raw(String(max))}`,
  );

/** Builds `column in ('a', 'b')` from a vocabulary list. The values are our own constants. */
export const inList = (column: AnyPgColumn, values: readonly string[]) =>
  sql`${column} in (${sql.raw(values.map((value) => `'${value}'`).join(', '))})`;
